        
var base64Logo = "data:image/png;base64,"; // Reemplaza esto con tu cadena Base64 completa     

/* funcion que se ejecuta con la interraccion en input range */
function actualizar() {
  //obtener el valor del input rango
  rango = document.getElementsByName("numero-pago")[0];
  valor = rango.value;

  //elemento donde se muetra el numero de cuotas y porcentaje
  campo = document.getElementById("numero-value");
  porcentaje = "";

  //obtener el valor del credito, limpiarle los puntos y conventirlo a numero float
  valorCredito = $("#valor-credito").val();
  valorCredito = valorCredito.replace(/\./g, "");
  valorCredito = parseFloat(valorCredito);

  //si el numero de cuotas es 6 valor es 1
  if (valor == 1) {
    
    valor = 6;
    porcentaje = "<br> Tasa de Interés del 2%";

  //si el numero de cuotas es 12 valor es 2
  } else if (valor == 2) {
    valor = 12;
    porcentaje = "<br> Tasa de Interés del 3%";
  }

  //modificar y mostrar en html
  campo.innerHTML = valor + " Cuotas Mensuales" + porcentaje;
}
