var cuotas;
var i;
var cuotaInicial; //porcentaje
var cuotaFinal; //porcentaje
var valorInicial; //valor de cuota inicial
var valorFinanciar;
var porcentajeIntereses;
var saldo;
var cuota; //porcentaje
var intereses;
var pago;
var minimoCop = 20000000;
var minimoUsd = 8000;
var minimoCop2 = 60000000;
var minimoUsd2 = 16000;

/* funcion que calcula el valor de las cuotas y lo muestra en un modal */
function calcular() {
  //limpiar contenido de tabla
  $("#tbody").html("");
  credito = document.getElementById("valor-credito");
  valorCredito = credito.value;
  //limpiar los puntos de los numeros
  valorCredito = valorCredito.replace(/\./g, "");
  //convertir a numero
  valorCredito = parseFloat(valorCredito);
  //obtener el numero de cuotas
  rango = document.getElementsByName("numero-pago")[0];
  valor = rango.value;
  
  //validar si el valor del credito esta vacio
  if (valorCredito == "") {

    alert("Llenar campos");

    //validar el valor minimo en pesos colombianos
  } else if(moneda == "COP" && valorCredito < minimoCop){

    alert("El valor no aplica para financiar");
    return;
    //validar el valor minimo en pesos para 12 cuotas
  } else if(moneda == "COP" && valorCredito >= minimoCop && valorCredito < minimoCop2 && valor == 2){

    alert("El numero de 12 cuotas no aplica para este valor");
    return;
    //validar el valor minimo en dolares
  }  else if(moneda == "USD" && valorCredito < minimoUsd){

    alert("El valor no aplica para financiar");
    return;
    //validar el valor minimo en dolares para 12 cuotas
  }  else if(moneda == "USD" && valorCredito >= minimoUsd && valorCredito < minimoUsd2 && valor == 2){

    alert("El numero de 12 cuotas no aplica para este valor");
    return;
    //ejecutar si pasó todas las validaciones
  } else {

    //si se seleccionó la opcion de 6 cuotas
    if (valor == 1) {
      //primera opcion de cuotas

      cuotas = 6; //numeor de cuotas
      i = 1;
      cuotaInicial = 50; //porcentaje
      cuotaFinal = 0; //porcentaje
      valorInicial = calcularPorcentaje(valorCredito, cuotaInicial); //valor de cuota inicial
      valorFinanciar = parseFloat(valorCredito) - parseFloat(valorInicial);
      porcentajeIntereses = 2;
      saldo = parseFloat(valorFinanciar);
      cuota = parseFloat(valorFinanciar / cuotas); //porcentaje
      tasaDecimal = porcentajeIntereses / 100;

      //formula de amortizacion 
      pago = (valorFinanciar * tasaDecimal) / (1 - Math.pow(1 + tasaDecimal, -cuotas));

      //agregar la cuota inicial a la tabla html
      $("#tbody").append(
        `<tr>
            <th scope="row">Cuota inicial</th>
            <td>$ ` +
          convertirNumero(Math.round(valorInicial)) +" "+moneda+
          `</td>
        </tr>`
      );

      //iterar el numero de cuotas
      while (cuotas >= i) {
        intereses = calcularPorcentaje(saldo, porcentajeIntereses);

        saldo = saldo - cuota;

        //llenar la tabla con todas las cuotas fijas
        $("#tbody").append(
          `<tr>
                <th scope="row">Cuota ` + i +
            `</th>
                <td>$ ` + convertirNumero(Math.round(pago)) +" "+moneda+
            `</td>
            </tr>`
        );
        i++;
      }

      total = parseFloat(intereses) + valorCredito;

      //si se seleccionó la opcion de 12 cuotas
    } else if (valor == 2) {
      cuotas = 12;
      i = 1;
      cuotaInicial = 50; //porcentaje
      cuotaFinal = 0; //porcentaje
      valorInicial = calcularPorcentaje(valorCredito, cuotaInicial); //valor de cuota inicial
      valorFinanciar = parseFloat(valorCredito) - parseFloat(valorInicial); //valor del credito
      porcentajeIntereses = 3; //porcentaje de intereses
      saldo = parseFloat(valorFinanciar); 
      cuota = parseFloat(valorFinanciar / cuotas); //porcentaje
      tasaDecimal = porcentajeIntereses / 100;

      //formula de amortizacion
      pago = (valorFinanciar * tasaDecimal) / (1 - Math.pow(1 + tasaDecimal, -cuotas));

      //agregar cuota inicial a la tabla html
      $("#tbody").append(
        `<tr>
            <th scope="row">Cuota inicial</th>
            <td>$ ` + convertirNumero(Math.round(valorInicial)) +" "+moneda+`</td>
        </tr>`
      );

      //iterar el numero de cuotas
      while (cuotas >= i) {
        intereses = calcularPorcentaje(saldo, porcentajeIntereses);
        saldo = saldo - cuota;

        // llenar contenido de tabla html
        $("#tbody").append(
          `<tr>
              <th scope="row">Cuota ` + i + `</th>
              <td>$ ` + convertirNumero(Math.round(pago)) +" "+moneda+`</td>
          </tr>`
        );
        i++;
      }

      total = parseFloat(intereses) + valorCredito;
    }

    //mostrar modal con la tabla html
    $("#modalCredito").modal("show");
  }
}
